/*
 * A329580  For every n >= 0, exactly 10 sums are prime among a(n+i) + a(n+j),
 *          0 <= i < j < 8: lexicographically earliest such sequence of
 *          distinct nonnegative numbers.
 * https://oeis.org/A329580
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is defined by the lexicographically earliest sequence of
 *            distinct non‑negative integers such that for every block of 8
 *            consecutive terms exactly 10 of the 28 pairwise sums are prime.
 *            The sequence is generated by a greedy search: at each step the
 *            smallest unused non‑negative integer that pres...
 * Range:     u8 n <= 53, u16 n <= 82, u32 n <= 82, u64 n <= 82, u128 n <= 82,
 *            big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include "../utils/is_prime_big.h"

static seq_t *seq_cache = NULL;      /* array of computed terms               */
static size_t   cache_len = 0;        /* number of terms actually filled       */
static size_t   cache_cap = 0;        /* allocated length of seq_cache         */

static seq_t *used_vals = NULL;      /* array of used values                 */
static size_t   used_len = 0;         /* number of used values                */
static size_t   used_cap = 0;         /* allocated length of used_vals        */

/* add a new value to the used values array */
static void add_used(seq_t v)
{
    if (used_len >= used_cap) {
        size_t new_cap = used_cap == 0 ? 16 : used_cap << 1;
        seq_t *tmp = (seq_t *)realloc(used_vals, new_cap * sizeof(seq_t));
        if (!tmp) exit(1);
        used_vals = tmp;
        used_cap = new_cap;
    }
    used_vals[used_len++] = v;
}

/* linear search for a value; cost O(used_len) which is ≤ 1e4 */
static bool used_contains(seq_t v)
{
    for (size_t i = 0; i < used_len; ++i)
        if (used_vals[i] == v) return true;
    return false;
}

/* initialise the first seven terms 0..6 */
static void init_base_terms(void)
{
    while (cache_len < 7) {
        if (cache_len >= cache_cap) {
            size_t new_cap = cache_cap == 0 ? 16 : cache_cap << 1;
            seq_t *tmp = (seq_t *)realloc(seq_cache, new_cap * sizeof(seq_t));
            if (!tmp) exit(1);
            seq_cache = tmp;
            cache_cap = new_cap;
        }
        seq_cache[cache_len] = (seq_t)cache_len;
        add_used((seq_t)cache_len);
        ++cache_len;
    }
}

/* ensures that at least n terms are computed (n >= 1) */
static void ensure_cache(idx_t n)
{
    if (cache_len >= (size_t)n) return;   /* already have enough terms        */
    if (cache_len == 0) init_base_terms();

    while (cache_len < (size_t)n) {
        seq_t chosen = 0;
        seq_t cand = 0;

        /* find smallest unused candidate yielding 10 prime sums */
        for (;;) {
            if (used_contains(cand)) { ++cand; continue; }

            seq_t w[8];
            size_t start = cache_len - 7;   /* last 7 terms exist */
            for (int i = 0; i < 7; ++i) w[i] = seq_cache[start + i];
            w[7] = cand;

            int prime_cnt = 0;
            for (int i = 0; i < 8; ++i) {
                for (int j = i + 1; j < 8; ++j) {
                    seq_t s = w[i] + w[j];
                    if (is_prime_big(s)) ++prime_cnt;
                }
            }
            if (prime_cnt == 10) {
                chosen = cand;
                break;
            }
            ++cand;
        }

        add_used(chosen);

        if (cache_len >= cache_cap) {
            size_t new_cap = cache_cap == 0 ? 16 : cache_cap << 1;
            seq_t *tmp = (seq_t *)realloc(seq_cache, new_cap * sizeof(seq_t));
            if (!tmp) exit(1);
            seq_cache = tmp;
            cache_cap = new_cap;
        }
        seq_cache[cache_len++] = chosen;
    }
}

seq_t a(idx_t n)
{
    /* ensure we have computed terms 0 .. n (inclusive) */
    ensure_cache(n + 1);
    return seq_cache[n];
}
